const fresh=()=>({version:1,clubId:"ACC",season:2026,round:0,money:1250000,fans:7200,formation:"4-3-3",mentality:"Balanced",pressing:"Standard",training:"Balanced",subStrategy:"Balanced",lineup:[],players:raw.map((p,i)=>({id:i+1,name:p[0],pos:p[1],age:p[2],rating:p[3],potential:p[4],fitness:88+(i*7)%13,morale:70+(i*5)%24,yellowCards:0,suspendedMatches:0,contractYears:2+(i%3),wage:250+p[3]*35})),table:clubs.map(c=>({id:c.id,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]})),fixtures:makeFixtures(),history:[],last:null,facilities:{training:1,youth:1,medical:1},marketPlayers:initialMarket.map(p=>({...p})),academy:[],academyNextId:200});
