const club=id=>clubs.find(c=>c.id===id)||clubs[0], mine=()=>club(state.clubId), table=id=>state.table.find(t=>t.id===id), money=n=>new Intl.NumberFormat("en-GH",{style:"currency",currency:"GHS",maximumFractionDigits:0}).format(n), compact=n=>n>=1e6?"GH₵"+(n/1e6).toFixed(2)+"m":"GH₵"+Math.round(n/1000)+"k", esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
