function xi(){let used=new Set(),ranked=[...state.players].filter(p=>(p.injuryMatches||0)===0&&(p.suspendedMatches||0)===0).sort((a,b)=>b.rating+(b.fitness-80)*.12-(a.rating+(a.fitness-80)*.12));return shapes[state.formation].map(([pos,x,y],i)=>{const chosen=state.lineup[i],manual=ranked.find(p=>p.id===Number(chosen)&&!used.has(p.id)&&fits(p.pos,pos));let p=manual||ranked.find(p=>!used.has(p.id)&&fits(p.pos,pos))||ranked.find(p=>!used.has(p.id));if(p)used.add(p.id);return{p,pos,x,y}}).filter(x=>x.p)}
function lineupEditor(){const starters=xi();return '<div class="lineup-editor"><div class="small-label">CUSTOM STARTING XI</div><p class="subtext">Choose your own starters. Injured or suspended players cannot be selected.</p>'+shapes[state.formation].map(([pos],i)=>{const current=starters[i]?.p?.id;const used=new Set(starters.filter((x,j)=>j!==i).map(x=>x.p.id));const options=state.players.filter(p=>(p.injuryMatches||0)===0&&(p.suspendedMatches||0)===0&&!used.has(p.id)&&(fits(p.pos,pos)||p.id===current)).sort((a,b)=>b.rating-a.rating);return '<label class="lineup-row"><span>'+(i+1)+'. '+pos+'</span><select class="select-wide lineup-select" data-slot="'+i+'">'+options.map(p=>'<option value="'+p.id+'" '+(p.id===current?"selected":"")+'>'+esc(p.name)+' · '+p.rating+'</option>').join("")+'</select></label>'}).join("")+'</div>'}
function fits(a,b){if(a===b)return true;if(["RB","LB","RWB","LWB"].includes(a)&&["RB","LB","RWB","LWB"].includes(b))return true;if(["CM","DM","AM"].includes(a)&&["CM","DM","AM"].includes(b))return true;if(["RW","LW","RM","LM"].includes(a)&&["RW","LW","RM","LM"].includes(b))return true;if(a==="ST"&&["ST","CF"].includes(b))return true;return a==="CB"&&b==="CB"}
function squadProfile(id){if(id!==state.clubId){const rating=club(id).strength;return {rating,attack:rating+(id.charCodeAt(0)%5),defence:rating+(id.charCodeAt(1)%5),passing:rating+(id.charCodeAt(2)%4),fitness:82}}const starters=xi(),n=Math.max(1,starters.length),avg=fn=>starters.reduce((sum,x)=>sum+fn(x.p),0)/n;return {rating:avg(p=>p.rating),attack:avg(p=>{const a=playerAttributes(p);return a.shooting*.55+a.pace*.2+a.passing*.25}),defence:avg(p=>{const a=playerAttributes(p);return (p.pos==="GK"?a.goalkeeping:a.defending)*.65+a.passing*.15+p.rating*.2}),passing:avg(p=>playerAttributes(p).passing),fitness:avg(p=>p.fitness)}}
function power(id,home){const c=club(id),profile=squadProfile(id);if(id!==state.clubId)return c.strength+(home?3:0);return profile.rating+(profile.fitness-80)*.12+(state.formation==="4-3-3"?2:1)+(state.mentality==="Attacking"?3:state.mentality==="Defensive"?-2:0)+(state.pressing==="High"?(profile.fitness>78?2:-2):state.pressing==="Low"?-1:0)+(home?4:0)}
function matchNarrative(m){const home=club(m.home).name,away=club(m.away).name;return m.homeGoals>m.awayGoals?home+" take all three points after a decisive performance.":m.homeGoals<m.awayGoals?away+" leave with all three points after a decisive performance.":"Neither side could be separated; the points are shared."}
function simulate(m){
 const h=club(m.home),a=club(m.away),hp=power(m.home,true),ap=power(m.away,false);
 const homeIsPlayer=m.home===state.clubId,awayIsPlayer=m.away===state.clubId;
 const homeProfile=squadProfile(m.home),awayProfile=squadProfile(m.away);
 const subPlans={home:null,away:null};
 if(homeIsPlayer||awayIsPlayer){const starters=new Set(xi().map(x=>x.p.id));const bench=state.players.filter(p=>!starters.has(p.id)&&(p.injuryMatches||0)===0&&(p.suspendedMatches||0)===0).sort((a,b)=>b.fitness-a.fitness||b.rating-a.rating).slice(0,3);const strategy=state.subStrategy||"Balanced";const impact=bench.length?bench.reduce((sum,p)=>{const a=playerAttributes(p);return sum+(strategy==="Attack"?(a.shooting*.55+a.pace*.3+a.passing*.15):strategy==="Protect Lead"?(a.defending*.55+a.goalkeeping*.15+a.passing*.3):(a.rating*.5+a.fitness*.5))},0)/bench.length:0;const boost=bench.length?Math.max(0,impact-55)*.045:0;if(homeIsPlayer)subPlans.home={bench,boost,strategy};if(awayIsPlayer)subPlans.away={bench,boost,strategy}}
 const strengthGap=Math.max(-18,Math.min(18,hp-ap));
 const passingGap=Math.max(-18,Math.min(18,homeProfile.passing-awayProfile.passing));
 const homePossession=Math.max(28,Math.min(72,Math.round(50+strengthGap*.25+passingGap*.32+(Math.random()*8-4))));
 let hg=0,ag=0,homeShots=0,awayShots=0,events=[];
 const attackers=()=>state.players.filter(p=>["ST","LW","RW","AM","CM"].includes(p.pos)).sort((x,y)=>{const ax=playerAttributes(x),ay=playerAttributes(y);return (ay.shooting*.7+ay.pace*.2+ay.passing*.1)-(ax.shooting*.7+ax.pace*.2+ax.passing*.1)});
 const scorerFor=(isHome)=>{
  const controlled=(isHome&&homeIsPlayer)||(!isHome&&awayIsPlayer);
  if(!controlled)return (isHome?h.name:a.name).split(" ")[0]+" forward";
  const pool=attackers(),weighted=pool.filter(p=>["ST","LW","RW","AM"].includes(p.pos));
  const choices=weighted.length?weighted:pool;
  if(!choices.length)return "Your forward";
  const player=choices[Math.floor(Math.random()*choices.length)];
  return player.name.split(" ").slice(-1)[0];
 };
 for(let minute=1;minute<=90;minute++){
  if(minute===45)events.push({minute,type:"halftime",text:"Half-time: "+h.name+" "+hg+"–"+ag+" "+a.name+". Both managers have a chance to reset."});
  if(minute===61){for(const side of ["home","away"]){const plan=subPlans[side];if(plan&&plan.bench.length){const teamName=side==="home"?h.name:a.name;events.push({minute,type:"substitution",text:teamName+" make "+plan.bench.length+" tactical substitution(s) ("+plan.strategy+"): "+plan.bench.map(p=>p.name).join(", ")+". "});}}}
  const isHome=Math.random()<homePossession/100;
  const teamPower=isHome?hp:ap,opponentPower=isHome?ap:hp;
  const attackingProfile={...(isHome?homeProfile:awayProfile)},defendingProfile={...(isHome?awayProfile:homeProfile)};
  const teamId=isHome?m.home:m.away;
  const attackingPlan=subPlans[isHome?"home":"away"],defendingPlan=subPlans[isHome?"away":"home"];
  if(minute>=61&&attackingPlan){if(attackingPlan.strategy==="Attack")attackingProfile.attack+=attackingPlan.boost*1.8;else if(attackingPlan.strategy==="Balanced")attackingProfile.attack+=attackingPlan.boost*.8;attackingProfile.passing+=attackingPlan.boost*.4}
  if(minute>=61&&defendingPlan){if(defendingPlan.strategy==="Protect Lead")defendingProfile.defence+=defendingPlan.boost*1.8;else defendingProfile.defence+=defendingPlan.boost*.4}
  const controlled=(isHome&&homeIsPlayer)||(!isHome&&awayIsPlayer);
  const formationBonus=controlled?(state.formation==="4-3-3"?0.025:state.formation==="3-5-2"?0.012:0):0;
  const substitutionBonus=controlled&&minute>=61&&subPlans[isHome?"home":"away"]?(subPlans[isHome?"home":"away"].strategy==="Attack"?.018:subPlans[isHome?"home":"away"].strategy==="Balanced"?.008:0):0;
  const mentalityBonus=controlled?(state.mentality==="Attacking"?0.035:state.mentality==="Defensive"?-0.018:0):0;
  const pressingBonus=controlled?(state.pressing==="High"?(state.players.reduce((sum,p)=>sum+p.fitness,0)/state.players.length>72?0.018:-0.012):state.pressing==="Low"?-0.008:0):0;
  const attackChance=Math.max(.035,Math.min(.30,.105+(teamPower-opponentPower)*.003+formationBonus+mentalityBonus+pressingBonus+substitutionBonus));
  if(Math.random()<.25){
   if(isHome)homeShots++;else awayShots++;
   const quality=Math.random();
   const attackEdge=Math.max(-20,Math.min(20,attackingProfile.attack-defendingProfile.defence));
   const goalChance=Math.max(.025,Math.min(.32,.055+quality*.105+(teamPower-opponentPower)*.0015+attackEdge*.0025+formationBonus+mentalityBonus+pressingBonus+substitutionBonus));
   if(Math.random()<goalChance){
    if(isHome)hg++;else ag++;
    events.push({minute,type:"goal",text:scorerFor(isHome)+" scores for "+(isHome?h.name:a.name)+"."});
   }else if(quality>.82&&Math.random()<.48){
    events.push({minute,type:"chance",text:(isHome?h.name:a.name)+" threaten, but the chance goes begging."});
   }
  }else if(Math.random()<attackChance*.45&&Math.random()<.12){
   events.push({minute,type:"chance",text:(isHome?h.name:a.name)+" work the ball into a dangerous area."});
  }
  if(Math.random()<.012){
   events.push({minute,type:"card",text:(isHome?h.name:a.name)+" receive a yellow card."});
  }
 }
 events.push({minute:90,type:"whistle",text:"Full-time: "+h.name+" "+hg+"–"+ag+" "+a.name+". "+matchNarrative({...m,homeGoals:hg,awayGoals:ag})});
 events.sort((x,y)=>x.minute-y.minute);
 return {...m,homeGoals:hg,awayGoals:ag,events,homeShots,awayShots,homePossession,played:true,date:"Matchday "+(state.round+1)};
}
function resultUpdate(m){for(let id of [m.home,m.away]){let t=table(id),gf=id===m.home?m.homeGoals:m.awayGoals,ga=id===m.home?m.awayGoals:m.homeGoals;t.p++;t.gf+=gf;t.ga+=ga;if(gf>ga){t.w++;t.pts+=3;t.form.unshift("W")}else if(gf===ga){t.d++;t.pts++;t.form.unshift("D")}else{t.l++;t.form.unshift("L")}t.form=t.form.slice(0,5)}}
function updatePlayingTime(startingIds,my,opp){const news=[];for(const p of state.players){const started=startingIds.has(p.id);if(started){p.starts=(p.starts||0)+1;p.appearances=(p.appearances||0)+1;p.morale=Math.min(99,p.morale+2+(my>opp?1:0));}else{p.morale=Math.max(20,p.morale-1);if((p.appearances||0)>=3&&(p.starts||0)/(p.appearances||1)<.35&&p.morale<48)news.push(p.name+" is unhappy with limited minutes");}}return [...new Set(news)].slice(0,2)}
function kickOff(){let f=current();if(!f){notify("Season complete — start another season in Club.");return}if(f.played){notify("This fixture is already played.");return}const starters=xi(),startingIds=new Set(starters.map(x=>x.p.id));let m=simulate(f);const userHome=m.home===state.clubId,userGoals=userHome?m.homeGoals:m.awayGoals,oppGoals=userHome?m.awayGoals:m.homeGoals;m.playerRatings=starters.map(({p,pos})=>{const lastName=p.name.split(" ").slice(-1)[0],scored=m.events.filter(e=>e.type==="goal"&&e.text.includes(lastName+" scores")).length;const resultImpact=userGoals>oppGoals?.45:userGoals===oppGoals?.1:-.35;const rating=Math.max(4,Math.min(10,Math.round((6.1+(p.rating-65)*.035+(p.fitness-80)*.018+(p.morale-70)*.008+resultImpact+scored*.8+(Math.random()-.5)*1.2)*10)/10));return {id:p.id,name:p.name,pos,rating,goals:scored}}).sort((a,b)=>b.rating-a.rating);m.playerOfMatch=m.playerRatings[0]?.name||"No award";Object.assign(f,m);resultUpdate(m);state.last=m;state.history.push(m);state.round++;let home=m.home===state.clubId,my=home?m.homeGoals:m.awayGoals,opp=home?m.awayGoals:m.homeGoals,reward=my>opp?85000:my===opp?55000:35000;state.players.forEach(p=>{if((p.injuryMatches||0)>0)p.injuryMatches--;if((p.suspendedMatches||0)>0)p.suspendedMatches--;});let injuryNotice="";if(Math.random()<.09){const available=state.players.filter(p=>(p.injuryMatches||0)===0);if(available.length){const hurt=available[Math.floor(Math.random()*available.length)];hurt.injuryMatches=1+Math.floor(Math.random()*3);injuryNotice=hurt.name+" injured ("+hurt.injuryMatches+" matchday"+(hurt.injuryMatches===1?"":"s")+").";m.events.push({minute:Math.floor(Math.random()*90)+1,type:"injury",text:hurt.name+" picks up an injury and will miss "+hurt.injuryMatches+" matchday(s)."});m.events.sort((a,b)=>a.minute-b.minute);}}let disciplineNotice="";const disciplinaryPool=state.players.filter(p=>(p.injuryMatches||0)===0&&(p.suspendedMatches||0)===0);if(disciplinaryPool.length&&Math.random()<.28){const booked=disciplinaryPool[Math.floor(Math.random()*disciplinaryPool.length)];if(Math.random()<.035){booked.suspendedMatches=2;booked.yellowCards=0;disciplineNotice=booked.name+" sent off and suspended for 2 matchdays.";m.events.push({minute:Math.floor(Math.random()*90)+1,type:"card",text:booked.name+" receives a red card and a two-match suspension."});}else{booked.yellowCards=(booked.yellowCards||0)+1;if(booked.yellowCards>=3){booked.yellowCards=0;booked.suspendedMatches=1;disciplineNotice=booked.name+" suspended for 1 matchday after accumulating 3 yellow cards.";m.events.push({minute:Math.floor(Math.random()*90)+1,type:"card",text:booked.name+" reaches three yellow cards and is suspended for the next match."});}else{disciplineNotice=booked.name+" booked ("+booked.yellowCards+"/3 yellow cards).";m.events.push({minute:Math.floor(Math.random()*90)+1,type:"card",text:booked.name+" receives a yellow card ("+booked.yellowCards+"/3 in the season)."});}}m.events.sort((a,b)=>a.minute-b.minute);}const playingTimeNews=updatePlayingTime(startingIds,my,opp);const developmentNews=developPlayers();const bidNews=createIncomingOffer();const marketNews=updateTransferMarket();state.money+=reward;const payroll=state.players.reduce((sum,p)=>sum+weeklyWage(p),0);state.money-=payroll;state.last.payroll=payroll;state.fans=Math.max(1000,state.fans+(my>opp?220:my===opp?25:-60));state.players.forEach(p=>{p.fitness=Math.max(40,p.fitness-(state.pressing==="High"?12:state.pressing==="Standard"?8:5)+Math.floor(Math.random()*4));p.morale=Math.max(35,Math.min(99,p.morale+(my>opp?4:my===opp?1:-4)))});save();notify((my>opp?"Win":my===opp?"Draw":"Defeat")+" — "+my+"–"+opp+". Payroll: "+money(payroll)+"."+(developmentNews.length?" Development: "+developmentNews.join(", ")+".":"")+(injuryNotice?" "+injuryNotice:"")+(disciplineNotice?" "+disciplineNotice:"")+(playingTimeNews.length?" Playing time: "+playingTimeNews.join(", ")+".":"")+(bidNews?" "+bidNews:"")+(marketNews?" "+marketNews:""));render("match")}
function head(k,t,s,action=""){return '<div class="page-head"><div><div class="eyebrow">'+k+'</div><h1>'+t+'</h1><p class="subtext">'+s+'</p></div>'+action+'</div>'}
function stat(k,v,n){return '<div class="stat-card"><div class="stat-label">'+k+'</div><div class="stat-value">'+v+'</div><div class="stat-note">'+n+'</div></div>'}
function panelHead(t,s=""){return '<div class="panel-head"><h2>'+t+'</h2><small>'+s+'</small></div>'}
function crest(c,away=false){return '<div class="team-badge '+(away?"away":"")+'">'+esc(c.id)+'</div>'}
function form(t){return '<div class="form-dots">'+(t.form.length?t.form:["–"]).map(x=>'<span class="form-dot '+x+'">'+x+'</span>').join("")+'</div>'}
function league(){return '<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>Club</th><th class="num">P</th><th class="num">GD</th><th class="num">Pts</th><th>Form</th></tr></thead><tbody>'+rows().map((t,i)=>'<tr class="'+(t.id===state.clubId?"highlight-row":"")+'"><td>'+String(i+1).padStart(2,"0")+'</td><td><div class="club-cell"><span class="mini-crest">'+t.id+'</span>'+esc(club(t.id).name)+'</div></td><td class="num">'+t.p+'</td><td class="num">'+(t.gf-t.ga>0?"+":"")+(t.gf-t.ga)+'</td><td class="num"><b>'+t.pts+'</b></td><td>'+form(t)+'</td></tr>').join("")+'</tbody></table></div>'}
function matchCard(){let m=current();if(!m)return '<section class="panel"><h2>Season complete</h2><p class="subtext">Your first season is in the books.</p><button class="btn primary" data-action="new-season">Start next season</button></section>';let h=club(m.home),a=club(m.away);return '<section class="panel next-match"><div class="match-meta"><span>UP NEXT · MATCHDAY '+(state.round+1)+'</span><span>GHANA PREMIER DIVISION</span></div><div class="match-teams"><div>'+crest(h)+'<div class="team-name">'+esc(h.name)+'</div></div><div class="versus">VS</div><div>'+crest(a,true)+'<div class="team-name">'+esc(a.name)+'</div></div></div><div class="match-footer"><span class="muted" style="font-size:11px">'+(m.home===state.clubId?"Home fixture":"Away fixture")+'</span><button class="btn primary" data-view="match">Prepare for match →</button></div></section>'}
function results(){let list=[...state.history].reverse().slice(0,4);return list.length?'<div class="list">'+list.map(m=>'<div class="list-row"><div class="list-icon">⚽</div><div class="list-main"><strong>'+esc(club(m.home).name)+' vs '+esc(club(m.away).name)+'</strong><small>'+m.date+'</small></div><div class="list-end">'+m.homeGoals+' – '+m.awayGoals+'</div></div>').join("")+'</div>':'<div class="empty-state">Your season starts here. Play your first match to see results.</div>'}
function dashboard(){let t=table(state.clubId);return head("MANAGER'S OFFICE","Build something legendary.","A new season. A hungry squad. Your decisions shape everything.",'<button class="btn" data-action="save">Save career</button>')+'<div class="grid stats-grid">'+stat("LEAGUE POSITION","#"+(rows().findIndex(x=>x.id===state.clubId)+1),t.pts+" points · "+t.p+" played")+stat("TRANSFER BUDGET",compact(state.money),"Available club funds")+stat("SQUAD FITNESS",Math.round(state.players.reduce((s,p)=>s+p.fitness,0)/state.players.length)+"%","Team average fitness")+stat("SUPPORTERS",state.fans.toLocaleString("en-GH"),"Supporter base")+'</div>'+seasonStatsPanel()+'<div class="grid dashboard-grid"><div>'+matchCard()+'<section class="panel">'+panelHead("Recent results","LATEST MATCHES")+results()+'</section></div><div><section class="panel">'+panelHead("League table","ALL CLUBS")+league()+'<div style="margin-top:15px"><button class="btn" data-view="fixtures" style="width:100%">Full fixtures →</button></div></section><section class="panel">'+panelHead("Manager's inbox","BOARD UPDATE")+'<div class="list-row"><div class="list-icon">✦</div><div class="list-main"><strong>Board expectation</strong><small>Finish in the top half and build a competitive squad.</small></div></div><div class="list-row"><div class="list-icon">⚑</div><div class="list-main"><strong>Scouting note</strong><small>'+(nextOpp()?esc(nextOpp().name)+" are rated "+nextOpp().strength+". Prepare your tactical approach.":"Review the season and plan the next campaign.")+'</small></div></div></section></div></div>'}
function seasonPlayerStats(){const stats=new Map();for(const m of state.history||[]){for(const p of m.playerRatings||[]){const row=stats.get(p.id)||{id:p.id,name:p.name,apps:0,goals:0,ratingTotal:0,best:0};row.apps++;row.goals+=p.goals||0;row.ratingTotal+=p.rating||0;row.best=Math.max(row.best,p.rating||0);stats.set(p.id,row)}}return [...stats.values()].map(p=>({...p,average:p.ratingTotal/Math.max(1,p.apps)})).sort((a,b)=>b.goals-a.goals||b.average-a.average)}
function seasonStatsPanel(){const stats=seasonPlayerStats(),leaders=[...stats].sort((a,b)=>b.goals-a.goals||b.average-a.average).slice(0,5);return '<section class="panel">'+panelHead("Season performance","LEAGUE CAMPAIGN")+'<div class="grid stats-grid season-mini">'+stat("MATCHES PLAYED",state.history.length,"This season")+stat("GOALS BY STARTERS",stats.reduce((n,p)=>n+p.goals,0),"Tracked in match reports")+stat("PLAYERS RATED",stats.length,"Appearances recorded")+stat("TOP AVERAGE",stats.length?Math.max(...stats.map(p=>p.average)).toFixed(1):"—","Best player average")+'</div>'+(leaders.length?'<div class="table-wrap"><table class="data-table"><thead><tr><th>Player</th><th class="num">Apps</th><th class="num">Goals</th><th class="num">Avg. rating</th></tr></thead><tbody>'+leaders.map(p=>'<tr><td><b>'+esc(p.name)+'</b></td><td class="num">'+p.apps+'</td><td class="num">'+p.goals+'</td><td class="num rating">'+p.average.toFixed(1)+'</td></tr>').join("")+'</tbody></table></div>':'<div class="empty-state">Play your first match to start tracking player statistics.</div>')+'</section>'}
function squadPage(){let q=$("#player-search")?.value?.toLowerCase()||"",pos=$("#position-filter")?.value||"ALL",ps=state.players.filter(p=>(pos==="ALL"||p.pos===pos)&&p.name.toLowerCase().includes(q));return head("FIRST TEAM","The squad.","Manage player roles, fitness, morale, and potential.",'<button class="btn" data-action="rest">Recovery day</button>')+'<div class="grid stats-grid">'+stat("PLAYERS",state.players.length,"First-team squad")+stat("AVG. RATING",(state.players.reduce((s,p)=>s+p.rating,0)/state.players.length).toFixed(1),"Squad quality")+stat("AVG. FITNESS",Math.round(state.players.reduce((s,p)=>s+p.fitness,0)/state.players.length)+"%","Match readiness")+stat("YOUNG PROSPECTS",state.players.filter(p=>p.age<=21).length,"Age 21 and under")+'</div>'+offersPanel()+seasonStatsPanel()+'<section class="panel"><div class="toolbar"><input class="input" id="player-search" placeholder="Search players…" value="'+esc($("#player-search")?.value||"")+'"><select id="position-filter"><option value="ALL">All positions</option>'+["GK","RB","CB","LB","DM","CM","AM","RW","LW","ST"].map(x=>'<option '+(pos===x?"selected":"")+'>'+x+'</option>').join("")+'</select><span class="tag">'+ps.length+' players</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Player</th><th>Pos</th><th>Age</th><th class="num">OVR</th><th>Fitness</th><th>Morale</th><th class="num">Potential</th><th>Availability</th><th class="num">Wage / matchday</th><th>Contract</th><th>Transfer</th></tr></thead><tbody>'+ps.map(p=>'<tr><td><b>'+esc(p.name)+'</b><div class="player-sub">'+(p.age<=21?"Young prospect":p.age>=29?"Experienced":"First team")+'</div>'+(p.age<=23&&p.rating<p.potential?'<div class="player-sub">Growth '+Math.round(p.developmentXP||0)+'%</div><div class="progress"><span style="width:'+Math.min(100,p.developmentXP||0)+'%"></span></div>':'')+'</td><td><span class="tag">'+p.pos+'</span></td><td>'+p.age+'</td><td class="num rating">'+p.rating+'</td><td><div style="display:flex;gap:8px;align-items:center"><div class="progress"><span style="width:'+p.fitness+'%"></span></div>'+p.fitness+'%</div></td><td>'+p.morale+'%</td><td class="num">'+p.potential+'</td><td>'+((p.injuryMatches||0)>0?'<span class="tag">Injured · '+p.injuryMatches+' MD</span>':(p.suspendedMatches||0)>0?'<span class="tag">Suspended · '+p.suspendedMatches+' MD</span>':'<span class="tag">'+(p.yellowCards||0)+'/3 yellow cards</span>')+'</td><td class="num">'+money(weeklyWage(p))+'</td><td><div class="player-sub">'+(p.contractYears>0?p.contractYears+" season"+(p.contractYears===1?"":"s")+" left":"Expired · renew now")+'</div><button class="btn" data-action="renew-contract" data-player="'+p.id+'" '+(state.money<Math.round(weeklyWage(p)*2)||p.contractYears>=4?"disabled":"")+'>'+(p.contractYears>=4?"Max term":"Renew")+'</button></td><td><button class="btn" data-action="sell-player" data-player="'+p.id+'" '+(state.players.length<=11?"disabled":"")+'>Sell</button></td></tr>').join("")+'</tbody></table></div></section>'+transferMarket()}
function offersPanel(){const offers=state.offers||[];return '<section class="panel">'+panelHead("Incoming bids",offers.length+" CLUB INTEREST")+(offers.length?'<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px">'+offers.map(o=>{const p=state.players.find(x=>x.id===o.playerId);return p?'<article class="panel facility"><h3>'+esc(p.name)+'</h3><p>'+esc(o.clubName)+' want to sign your '+p.pos+' · OVR '+p.rating+'</p><div class="facility-footer"><strong>'+money(o.fee)+'</strong><div><button class="btn" data-action="reject-offer" data-offer="'+o.id+'">Reject</button> <button class="btn primary" data-action="accept-offer" data-offer="'+o.id+'">Accept</button></div></div></article>':''}).join("")+'</div>':'<p class="subtext">No incoming bids right now. Other clubs may approach after matchdays for players who are performing well.</p>')+'</section>'}
function createIncomingOffer(){if(Math.random()>.22||!state.players.length)return null;const candidates=state.players.filter(p=>p.rating>=64&&p.age<31&&!state.offers.some(o=>o.playerId===p.id));if(!candidates.length)return null;const p=candidates[Math.floor(Math.random()*candidates.length)],rivals=clubs.filter(c=>c.id!==state.clubId),c=rivals[Math.floor(Math.random()*rivals.length)],value=Math.round((p.rating*2200+Math.max(0,p.potential-p.rating)*900+Math.max(0,27-p.age)*1800)/1000)*1000;const offer={id:Date.now(),playerId:p.id,clubId:c.id,clubName:c.name,fee:Math.round(value*(1.05+Math.random()*.45)/5000)*5000};state.offers.push(offer);return p.name+" has attracted a "+money(offer.fee)+" bid from "+c.name+"."}
function acceptOffer(id){const o=state.offers.find(x=>x.id===id);if(!o)return;const p=state.players.find(x=>x.id===o.playerId);if(!p){state.offers=state.offers.filter(x=>x.id!==id);save();render("squad");return}if(state.players.length<=11){notify("Keep at least 11 players. Sign a replacement before accepting this bid.");return}state.players=state.players.filter(x=>x.id!==p.id);state.money+=o.fee;state.offers=state.offers.filter(x=>x.id!==id);save();notify(o.clubName+" signed "+p.name+" for "+money(o.fee)+".");render("squad")}
function rejectOffer(id){const o=state.offers.find(x=>x.id===id);state.offers=state.offers.filter(x=>x.id!==id);save();notify(o?"You rejected "+o.clubName+"'s bid.":"Bid removed.");render("squad")}
function playerAttributes(p){const n=(offset,lo=25,hi=96)=>Math.max(lo,Math.min(hi,p.rating+offset+Math.floor((p.id*7+offset*13)%11)-5));const gk=p.pos==="GK";return {pace:n(gk?-24:(["CB","DM"].includes(p.pos)?-8:5)),passing:n(["CM","AM","DM"].includes(p.pos)?8:-2),shooting:n(p.pos==="ST"?10:(["RW","LW","AM"].includes(p.pos)?4:-10)),defending:n(["GK","CB","RB","LB","DM"].includes(p.pos)?8:-8),goalkeeping:n(gk?18:-28),potential:p.potential}}
function scoutReport(p){return playerAttributes(p)}
function scoutPlayer(id){const p=(state.marketPlayers||[]).find(x=>x.id===id);if(!p)return;if((state.scoutedPlayers||[]).includes(id)){notify("Scouting report already available.");return}const fee=12000;if(state.money<fee){notify("Not enough funds to commission this scouting report.");return}state.money-=fee;state.scoutedPlayers.push(id);save();notify("Scouting report ready for "+p.name+".");render("squad")}
function transferMarket(){
 const market=state.marketPlayers||[],scouted=state.scoutedPlayers||[];
 return '<section class="panel transfer-market">'+panelHead("Transfer market","SCOUTING NETWORK")+'<p class="subtext">Commission a report before committing your transfer budget. Each report costs GH₵12,000 and reveals potential and key attributes.</p>'+(market.length?'<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px">'+market.map(p=>{const known=scouted.includes(p.id),report=known?scoutReport(p):null;return '<article class="panel facility"><div class="facility-icon">♙</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.pos)+' · Age '+p.age+' · OVR '+p.rating+'</p><div class="player-sub">'+(known?'Potential '+report.potential+' · Fitness '+p.fitness+'%':'Estimated potential '+Math.max(p.rating,p.potential-8)+'–'+Math.min(99,p.potential+4)+' · Unscouted')+'</div>'+(known?'<div class="scout-attributes"><div class="player-sub">Pace '+report.pace+' · Passing '+report.passing+'</div><div class="player-sub">Shooting '+report.shooting+' · Defending '+report.defending+'</div><div class="player-sub">Goalkeeping '+report.goalkeeping+'</div></div>':'')+'<div class="player-sub">Wage demand: '+money(250+p.rating*35)+' per matchday</div><div class="facility-footer"><strong>'+compact(p.fee)+'</strong><div style="display:flex;gap:6px;flex-wrap:wrap">'+(known?'':'<button class="btn" data-action="scout-player" data-player="'+p.id+'" '+(state.money<12000?'disabled':'')+'>Scout · GH₵12k</button>')+'<button class="btn '+(state.money>=p.fee?"primary":"")+'" data-action="buy-player" data-player="'+p.id+'" '+(state.money<p.fee?"disabled":"")+'>Sign player</button></div></div></article>'}).join("")+'</div>':'<div class="empty-state">No players currently available. The market will refresh in a future update.</div>')+'<div class="notice" style="margin-top:14px">Scouting reports are stored with your career. This is an early scouting model; detailed staff, regional scouting, and rival-club recruitment are planned.</div></section>';
}
function updateTransferMarket(){state.marketPlayers||=[];state.scoutedPlayers||=[];let note="";if(state.marketPlayers.length&&Math.random()<.2){const index=Math.floor(Math.random()*state.marketPlayers.length),signed=state.marketPlayers.splice(index,1)[0],rival=clubs.filter(c=>c.id!==state.clubId)[Math.floor(Math.random()*(clubs.length-1))];state.scoutedPlayers=state.scoutedPlayers.filter(id=>id!==signed.id);note=rival.name+" beat other clubs to sign "+signed.name+".";}if(state.marketPlayers.length<7&&Math.random()<.62){const names=["Kweku Amponsah","Mavis Osei","Faisal Osman","Akua Boateng","Nana Yeboah","Salifu Yakubu","Selina Tetteh","Edem Kpodo","Ishmael Baah","Adjoa Frimpong","Mubarak Sule","Kofi Nyame"];const positions=["GK","RB","CB","LB","DM","CM","AM","RW","LW","ST"];const rating=52+Math.floor(Math.random()*20),age=18+Math.floor(Math.random()*11),potential=Math.min(90,rating+5+Math.floor(Math.random()*19)),id=Math.max(100,...state.marketPlayers.map(p=>p.id),...state.players.map(p=>p.id))+1;state.marketPlayers.push({id,name:names[Math.floor(Math.random()*names.length)],pos:positions[Math.floor(Math.random()*positions.length)],age,rating,potential,fitness:78+Math.floor(Math.random()*23),morale:60+Math.floor(Math.random()*35),fee:Math.round((rating*2200+Math.max(0,potential-rating)*900+Math.max(0,27-age)*1800)/5000)*5000});if(!note)note="Scouts have added a new player to the transfer market."; }return note}
function buyPlayer(id){
 const p=(state.marketPlayers||[]).find(x=>x.id===id);
 if(!p){notify("That player is no longer available.");return}
 if(state.money<p.fee){notify("Your club cannot afford this transfer.");return}
 if(state.players.length>=30){notify("Squad limit reached. Sell a player first.");return}
 state.money-=p.fee;
 state.players.push({id:Math.max(0,...state.players.map(x=>x.id))+1,name:p.name,pos:p.pos,age:p.age,rating:p.rating,potential:p.potential,fitness:p.fitness,morale:p.morale,wage:250+p.rating*35,contractYears:3});
 state.marketPlayers=state.marketPlayers.filter(x=>x.id!==id);
 save();notify(p.name+" signed for "+mine().name+" on a 3-season contract.");render("squad");
}
function renewContract(id){const p=state.players.find(x=>x.id===id);if(!p)return;if(p.contractYears>=4){notify("This player already has the maximum 4-season contract.");return}const fee=Math.round(weeklyWage(p)*2),apps=p.appearances||0,share=apps?(p.starts||0)/apps:1,raise=Math.max(100,Math.round(weeklyWage(p)*((p.morale<45||(apps>=3&&share<.35))?.30:p.rating>=75?.22:p.rating>=68?.16:.10))),wage=weeklyWage(p)+raise;if(state.money<fee){notify("Not enough funds for the signing bonus of "+money(fee)+".");return}if(!confirm("Offer "+p.name+" a new 3-season deal?\nSigning bonus: "+money(fee)+"\nProposed wage: "+money(wage)+" per matchday."))return;const chance=Math.max(.25,Math.min(.96,.78+(p.morale-65)*.006+(share-.5)*.25+(wage/Math.max(1,weeklyWage(p))-1)*.18));if(Math.random()>chance){p.morale=Math.max(20,p.morale-5);save();notify(p.name+" rejected the offer. Improve morale and playing time before trying again.");render("squad");return}state.money-=fee;p.wage=wage;p.contractYears=3;p.morale=Math.min(99,p.morale+8);save();notify(p.name+" accepted a new 3-season contract.");render("squad")}
function sellPlayer(id){
 if(state.players.length<=11){notify("Keep at least 11 players in your squad.");return}
 const p=state.players.find(x=>x.id===id);if(!p)return;
 const fee=Math.round((p.rating*2200+Math.max(0,p.potential-p.rating)*900+Math.max(0,27-p.age)*1800)/1000)*1000;
 if(!confirm("Sell "+p.name+" for "+money(fee)+"? This cannot be undone."))return;
 state.players=state.players.filter(x=>x.id!==id);state.money+=fee;
 save();notify(p.name+" transferred for "+money(fee)+".");render("squad");
}
function tacticsPage(){return head("MATCH PREPARATION","Your tactical identity.","Every choice changes the balance between control, risk, and energy.")+'<div class="grid tactics-layout"><section class="panel">'+panelHead("Tactical board",state.formation)+'<div class="pitch"><div class="centre-circle"></div><div class="penalty top"></div><div class="penalty bottom"></div>'+xi().map(x=>'<div class="player-dot" style="left:'+x.x+'%;top:'+x.y+'%">'+esc(x.p.pos)+'<small>'+esc(x.p.name.split(" ").slice(-1)[0])+'</small></div>').join("")+'</div><div class="small-label" style="margin-top:14px">Starting XI · your selected lineup</div>'+lineupEditor()+'</section><section class="panel">'+panelHead("Team instructions","APPLY BEFORE KICK-OFF")+option("Formation","Team structure","formation",Object.keys(shapes))+option("Team mentality","Risk and attacking intent","mentality",["Defensive","Balanced","Attacking"])+option("Pressing intensity","More pressure drains fitness","pressing",["Low","Standard","High"])+option("Training focus","Weekly development direction","training",["Balanced","Fitness","Attacking","Defending","Youth"])+option("Substitution strategy","Automatic changes from minute 61","subStrategy",["Balanced","Attack","Protect Lead"])+'<div class="divider"></div><div class="notice">High pressing improves intensity but drains fitness. Attacking mentality adds risk; defensive setups reduce attacking power.</div><button class="btn primary" data-action="apply-tactics" style="width:100%">Apply tactical plan</button></section></div>'}
function option(title,sub,id,values){return '<div class="tactic-option"><div><strong>'+title+'</strong><small>'+sub+'</small></div><select class="select-wide" id="'+id+'">'+values.map(v=>'<option '+(state[id]===v?"selected":"")+'>'+v+'</option>').join("")+'</select></div>'}
function fixturesPage(){return head("GHANA PREMIER DIVISION","Fixtures & standings.","Follow the title race across 14 rounds of home and away football.")+'<section class="panel">'+panelHead("League standings","MATCHDAY "+Math.min(state.round+1,14))+league()+'</section><section class="panel">'+panelHead("Season fixtures","HOME & AWAY")+'<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px">'+state.fixtures.map((round,i)=>'<div class="fixture-round"><div class="fixture-round-head"><span>MATCHDAY '+(i+1)+'</span><span>'+(round.every(m=>m.played)?"COMPLETED":i===state.round?"NEXT UP":i<state.round?"COMPLETED":"UPCOMING")+'</span></div>'+round.map(m=>'<div class="fixture-game"><span class="club">'+esc(club(m.home).name)+'</span><span class="fixture-score">'+(m.played?m.homeGoals+" – "+m.awayGoals:"vs")+'</span><span class="club">'+esc(club(m.away).name)+'</span></div>').join("")+'</div>').join("")+'</div></section>'}
function matchPage(){let m=state.last,n=current();if(!m)return head("MATCH CENTRE","Matchday starts here.","Review your tactics, then take your team onto the pitch.")+'<div class="grid dashboard-grid"><section class="panel">'+panelHead("Pre-match briefing","MATCHDAY "+(state.round+1))+'<div class="list-row"><div class="list-icon">⚽</div><div class="list-main"><strong>'+(n?esc(club(n.home).name)+" vs "+esc(club(n.away).name):"Season complete")+'</strong><small>'+(n?(n.home===state.clubId?"Home advantage":"Away challenge"):"Start a new season to continue")+'</small></div></div><div class="divider"></div><p class="subtext">Shape: <b>'+state.formation+'</b> · '+state.mentality+' mentality · '+state.pressing+' press.</p><button class="btn primary" data-action="play-match" style="width:100%;margin-top:15px" '+(!n?"disabled":"")+'>'+(n?"Kick off match →":"Season complete")+'</button></section><section class="panel">'+panelHead("Matchday checklist")+'<div class="list-row"><div class="list-icon">⌘</div><div class="list-main"><strong>Set your tactics</strong><small>Pick a formation and match mentality.</small></div><button class="btn" data-view="tactics">Open</button></div><div class="list-row"><div class="list-icon">♙</div><div class="list-main"><strong>Check fitness</strong><small>Fatigued players perform below their level.</small></div><button class="btn" data-view="squad">Open</button></div></section></div>';return head("MATCH CENTRE","The final whistle.","Match report · "+m.date,'<button class="btn" data-view="fixtures">View fixtures</button>')+'<section class="match-scoreboard"><div class="score-meta">GHANA PREMIER DIVISION · '+m.date.toUpperCase()+'</div><div class="scoreline"><div>'+crest(club(m.home))+'<div class="team-name">'+esc(club(m.home).name)+'</div></div><span class="score-number">'+m.homeGoals+' – '+m.awayGoals+'</span><div>'+crest(club(m.away),true)+'<div class="team-name">'+esc(club(m.away).name)+'</div></div></div><span class="tag">FULL TIME</span></section><div class="grid dashboard-grid"><section class="panel">'+panelHead("Match statistics","90 MINUTES")+'<div class="tactic-option"><strong>Shots</strong><b>'+m.homeShots+' — '+m.awayShots+'</b></div><div class="tactic-option"><strong>Possession</strong><b>'+m.homePossession+'% — '+(100-m.homePossession)+'%</b></div><div class="tactic-option"><strong>Formation</strong><b>'+esc(state.formation)+'</b></div></section><section class="panel">'+panelHead("Match timeline","KEY MOMENTS")+(m.events.length?m.events.map(e=>'<div class="event-row"><span class="event-minute">'+e.minute+"′"+'</span><span class="event-symbol">'+(e.type==="goal"?"⚽":e.type==="card"?"🟨":e.type==="injury"?"✚":"↗")+'</span><span>'+esc(e.text)+'</span></div>').join(""):'<div class="empty-state">A tight match with few clear chances.</div>')+'</section></div><section class="panel">'+panelHead("Player ratings","YOUR STARTING XI")+'<div class="player-of-match"><span class="potm-icon">★</span><div><small>PLAYER OF THE MATCH</small><strong>'+esc(m.playerOfMatch||"Not available")+'</strong></div><b>'+(m.playerRatings?.[0]?.rating?.toFixed(1)||"—")+'</b></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Player</th><th>Pos</th><th class="num">Goals</th><th class="num">Rating</th></tr></thead><tbody>'+(m.playerRatings||[]).map(p=>"<tr><td><b>"+esc(p.name)+"</b></td><td><span class=\"tag\">"+esc(p.pos)+"</span></td><td class=\"num\">"+p.goals+"</td><td class=\"num rating\">"+p.rating.toFixed(1)+"</td></tr>").join("")+'</tbody></table></div></section><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn primary" data-view="dashboard">Back to overview</button><button class="btn" data-action="rest">Recover squad</button><button class="btn" data-view="fixtures">League table</button></div>'}
function academyPanel(){const prospects=state.academy||[];return '<section class="panel">'+panelHead("Youth academy","PATHWAY TO THE FIRST TEAM")+'<p class="subtext">Scout young prospects, track their growth, and promote the best talent. Higher academy levels improve intake quality.</p><div class="facility-footer" style="margin:14px 0"><span class="tag">Academy level '+state.facilities.youth+'</span><button class="btn primary" data-action="youth-intake" '+(state.money<45000||prospects.length>=6?'disabled':'')+'>Scout youth intake · GH₵45,000</button></div>'+(prospects.length?'<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px">'+prospects.map(p=>'<article class="panel facility"><div class="facility-icon">♧</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.pos)+' · Age '+p.age+' · OVR '+p.rating+'</p><div class="player-sub">Potential '+p.potential+' · Development '+Math.round(p.developmentXP||0)+'%</div><div class="progress"><span style="width:'+Math.min(100,p.developmentXP||0)+'%"></span></div><div class="facility-footer"><span class="tag">Academy prospect</span><button class="btn" data-action="promote-youth" data-player="'+p.id+'" '+(state.players.length>=30?'disabled':'')+'>Promote</button></div></article>').join('')+'</div>':'<div class="empty-state">No academy prospects yet. Scout an intake to discover young talent.</div>')+'<div class="notice" style="margin-top:12px">Young senior players improve gradually when their rating is below potential. Training and academy upgrades increase development speed.</div></section>'}
function youthIntake(){if(state.money<45000){notify("Not enough funds to scout youth players.");return}if(state.academy.length>=6){notify("Academy is full. Promote prospects before scouting again.");return}const names=["Kwaku Baffour","Akosua Nyarko","Yaw Kwarteng","Esi Mensimah","Kwabena Sasu","Mariam Yakubu","Nana Aidoo","Abdul Fatawu","Selorm Agbeko","Efua Osei","Kofi Danso","Amina Sule"];const positions=["GK","RB","CB","LB","DM","CM","AM","RW","LW","ST"];const count=Math.min(3,6-state.academy.length);state.money-=45000;for(let i=0;i<count;i++){const age=16+Math.floor(Math.random()*4),potential=Math.min(92,58+Math.floor(Math.random()*18)+(state.facilities.youth-1)*3),rating=Math.max(42,Math.min(potential-8,42+Math.floor(Math.random()*13)+(state.facilities.youth-1)*2)),pos=positions[Math.floor(Math.random()*positions.length)],name=names[Math.floor(Math.random()*names.length)];state.academy.push({id:state.academyNextId++,name,pos,age,rating,potential,fitness:90,morale:75,wage:250+rating*25,developmentXP:0,yellowCards:0,suspendedMatches:0,injuryMatches:0})}save();notify("Youth intake scouted. Review your new prospects.");render("club")}
function promoteYouth(id){const p=state.academy.find(x=>x.id===id);if(!p)return;if(state.players.length>=30){notify("Squad limit reached. Sell a player first.");return}state.academy=state.academy.filter(x=>x.id!==id);state.players.push({...p,id:Math.max(0,...state.players.map(x=>x.id))+1,contractYears:3});save();notify(p.name+" promoted to the senior squad.");render("club")}
function developPlayers(){const improved=[];state.players.forEach(p=>{if(p.age>23||p.rating>=p.potential)return;const focus=state.training==="Youth"?1.5:state.training==="Balanced"?1:0.75,fitnessFactor=p.fitness<55?.45:p.fitness<75?.75:1;const gain=(2.5+state.facilities.training*1.4+state.facilities.youth*.65)*focus*fitnessFactor*(p.age<=20?1.2:1);p.developmentXP=Math.min(100,(p.developmentXP||0)+gain);if(p.developmentXP>=100){p.rating=Math.min(p.potential,p.rating+1);p.developmentXP=0;improved.push(p.name+" reached "+p.rating+" OVR")}});(state.academy||[]).forEach(p=>{if(p.rating>=p.potential)return;const gain=(4+state.facilities.youth*2+state.facilities.training)*((p.age<=17)?1.2:1);p.developmentXP=Math.min(100,(p.developmentXP||0)+gain);if(p.developmentXP>=100){p.rating=Math.min(p.potential,p.rating+1);p.developmentXP=0}});return improved}
function clubPage(){let data=[["training","⚙","Training ground","Improves development.",300000],["youth","♧","Youth academy","Supports future prospects.",250000],["medical","✚","Medical centre","Upgrading reduces current injury recovery time.",220000]];return head("OFF THE PITCH","Build your club.","Manage your budget, facilities, and long-term future.")+'<section class="club-hero"><div class="crest">'+state.clubId+'</div><div><div class="eyebrow">YOUR CLUB · GHANA</div><h2>'+esc(mine().name)+'</h2><p>Home stadium · '+state.fans.toLocaleString("en-GH")+' supporters</p></div></section><div class="grid stats-grid">'+stat("AVAILABLE FUNDS",money(state.money),"After recent payroll")+stat("WAGE BILL",money(state.players.reduce((s,p)=>s+weeklyWage(p),0)),"Paid after each match")+stat("TRAINING LEVEL","Level "+state.facilities.training,"Player development")+stat("YOUTH LEVEL","Level "+state.facilities.youth,"Academy pathway")+'</div><section class="panel">'+panelHead("Club facilities","INVEST IN YOUR FUTURE")+'<div class="grid facilities-grid">'+data.map(([id,icon,name,desc,cost])=>'<article class="panel facility"><div class="facility-icon">'+icon+'</div><h3>'+name+'</h3><p>'+desc+'</p><div class="facility-footer"><span class="tag">Level '+state.facilities[id]+'</span><button class="btn '+(state.money>=cost?"primary":"")+'" data-action="upgrade" data-facility="'+id+'" data-cost="'+cost+'" '+(state.money<cost?"disabled":"")+'>'+compact(cost)+' · Upgrade</button></div></article>').join("")+'</div></section><section class="panel">'+panelHead("Career controls","LOCAL SAVE")+'<p class="subtext">Career data stays in this browser. Export a backup before clearing browser data or switching devices.</p><div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:16px"><button class="btn" data-action="export">Export career backup</button><label class="btn" for="import-save">Import career backup</label><input type="file" id="import-save" accept="application/json" hidden><button class="btn" data-action="save">Save now</button><button class="btn" data-action="new-season">Start next season</button></div></section>'+academyPanel()}
function render(to=page){page=to;const pages={dashboard,squad:squadPage,tactics:tacticsPage,fixtures:fixturesPage,match:matchPage,club:clubPage};$("#app").innerHTML=(pages[page]||dashboard)();all("[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===page));$("#club-name-side").textContent=mine().name;$("#season-side").textContent="Season "+state.season+"/"+String(state.season+1).slice(-2);$("#top-season").textContent="GHANA PREMIER DIVISION · "+state.season+"/"+String(state.season+1).slice(-2);const search=$("#player-search"),filter=$("#position-filter");if(search)search.addEventListener("input",()=>{let q=search.value,p=filter.value;render("squad");$("#player-search").value=q;$("#position-filter").value=p;$("#player-search").focus();$("#player-search").setSelectionRange(q.length,q.length)});if(filter)filter.addEventListener("change",()=>render("squad"));$("#import-save")?.addEventListener("change",importSave)}
function notify(msg){let el=$("#toast");el.textContent=msg;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),2600)}
function recover(){if(state.money<25000){notify("Not enough funds for recovery.");return}state.money-=25000;state.players.forEach(p=>{p.fitness=Math.min(100,p.fitness+(state.training==="Fitness"?18:12));p.morale=Math.min(99,p.morale+2)});save();notify("Recovery complete. Fitness restored.");render(page)}
function upgrade(id,cost){if(!state.facilities[id]||state.money<cost)return;state.money-=cost;state.facilities[id]++;if(id==="training")state.players.forEach(p=>{if(p.age<25)p.potential=Math.min(99,p.potential+1)});if(id==="medical")state.players.forEach(p=>{if((p.injuryMatches||0)>0)p.injuryMatches=Math.max(0,p.injuryMatches-1)});save();notify("Facility upgraded.");render("club")}
function newSeason(){if(!confirm("Start a new season? Results reset; squad and facilities carry forward."))return;state.season++;state.round=0;state.fixtures=makeFixtures();state.table=clubs.map(c=>({id:c.id,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0,form:[]}));state.last=null;state.history=[];const departed=[];state.players.forEach(p=>{p.age++;p.injuryMatches=0;p.suspendedMatches=0;p.yellowCards=0;p.wage=Math.round(weeklyWage(p)*1.05);p.fitness=Math.min(100,p.fitness+12);if(p.age<25&&p.rating<p.potential&&Math.random()<.65)p.rating++;p.contractYears=Math.max(0,(p.contractYears??2)-1)});state.players.filter(p=>p.contractYears===0).forEach(p=>{if(state.players.length-departed.length>11){departed.push(p);state.marketPlayers.push({id:Math.max(100,...state.marketPlayers.map(x=>x.id))+1,name:p.name,pos:p.pos,age:p.age,rating:p.rating,potential:p.potential,fitness:p.fitness,morale:p.morale,fee:0});}});if(departed.length){const ids=new Set(departed.map(p=>p.id));state.players=state.players.filter(p=>!ids.has(p.id));}save();notify("New season begins."+(departed.length?" "+departed.length+" player contract"+(departed.length===1?"":"s")+" expired; they are now free agents on the market.":""));render("dashboard")}
function exportSave(){let blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="project-touchline-career.json";a.click();URL.revokeObjectURL(url);notify("Career backup exported.")}
function importSave(e){let file=e.target.files?.[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result);if(x.version!==1||!Array.isArray(x.players)||!Array.isArray(x.fixtures)||!clubs.some(c=>c.id===x.clubId))throw Error();state=x;save();notify("Career backup imported.");render("dashboard")}catch{notify("That backup file is invalid.")}};reader.readAsText(file)}
document.addEventListener("change",e=>{const select=e.target.closest(".lineup-select");if(!select)return;const slot=Number(select.dataset.slot),id=Number(select.value);state.lineup[slot]=id;const duplicate=state.lineup.some((v,i)=>i!==slot&&Number(v)===id);if(duplicate){state.lineup[slot]=undefined;notify("A player can only occupy one starting position.");}state.lineup=state.lineup.slice(0,shapes[state.formation].length);save();render("tactics");});
document.addEventListener("click",e=>{let v=e.target.closest("[data-view]");if(v){e.preventDefault();render(v.dataset.view);return}let b=e.target.closest("[data-action]");if(!b)return;switch(b.dataset.action){case"play-match":kickOff();break;case"buy-player":buyPlayer(Number(b.dataset.player));break;case"scout-player":scoutPlayer(Number(b.dataset.player));break;case"sell-player":sellPlayer(Number(b.dataset.player));break;case"renew-contract":renewContract(Number(b.dataset.player));break;case"accept-offer":acceptOffer(Number(b.dataset.offer));break;case"reject-offer":rejectOffer(Number(b.dataset.offer));break;case"save":save();notify("Career saved on this device.");break;case"apply-tactics":for(let id of ["formation","mentality","pressing","training","subStrategy"])if($("#"+id))state[id]=$("#"+id).value;save();notify("Tactical plan applied.");render("tactics");break;case"rest":recover();break;case"upgrade":upgrade(b.dataset.facility,Number(b.dataset.cost));break;case"youth-intake":youthIntake();break;case"promote-youth":promoteYouth(Number(b.dataset.player));break;case"new-season":newSeason();break;case"export":exportSave();break}});
window.addEventListener("beforeunload",save);
if("serviceWorker"in navigator&&import.meta.env.PROD)window.addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(console.warn));
render();